s=s.replace(old_machine_trailing,new_machine_trailing,1)

third_anchor="""  @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Equipamentos de terceiros')),"""
third_remove="""  Future<void> removeThirdParty(Map<String,dynamic> x) async {\n    final label=_hasValue(x['plate'])?'${x['plate']}':'${x['description']??'este equipamento'}';\n    final ok=await showDialog<bool>(context:context,builder:(ctx)=>AlertDialog(\n      title:const Text('Excluir equipamento de terceiros?'),\n      content:Text('$label será retirado dos cadastros ativos. Todos os abastecimentos, relatórios, fotos, assinaturas e auditorias anteriores permanecerão preservados.'),\n      actions:[TextButton(onPressed:()=>Navigator.pop(ctx,false),child:const Text('Cancelar')),FilledButton(style:FilledButton.styleFrom(backgroundColor:Colors.red.shade700),onPressed:()=>Navigator.pop(ctx,true),child:const Text('Excluir'))],\n    ));\n    if(ok!=true)return;setState(()=>loading=true);\n    try{await api.archiveThirdParty(x);await load();if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Equipamento retirado dos cadastros ativos. Histórico preservado ✓')));}\n    catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(_friendlyError(e))));}\n    finally{if(mounted)setState(()=>loading=false);}\n  }\n"""+third_anchor
assert third_anchor in s
s=s.replace(third_anchor,third_remove,1)
old_third_tile="""onTap:loading?null:()=>edit(x),trailing:const Icon(Icons.edit_outlined))"""
new_third_tile="""onTap:loading?null:()=>edit(x),trailing:PopupMenuButton<String>(enabled:!loading,onSelected:(v){if(v=='edit')edit(x);if(v=='delete')removeThirdParty(x);},itemBuilder:(_)=>const [PopupMenuItem(value:'edit',child:Text('Editar')),PopupMenuItem(value:'delete',child:Text('Excluir',style:TextStyle(color:Colors.red))) ]))"""
assert old_third_tile in s
